def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1

    # Lamp i is bit i of x. The update y_i = sum_d x_{i+d} is multiplication
    # by Q(z) = sum_d z^{-d} in GF(2)[z]/(z^n - 1). Offsets that appear an
    # even number of times cancel, which XOR handles automatically.
    q = 0
    for d in offsets:
        q ^= 1 << ((-d) % n)

    def clmul(a: int, b: int) -> int:
        # Carry-less multiplication of two GF(2) polynomials.
        res = 0
        while a:
            low = a & -a
            res ^= b << (low.bit_length() - 1)
            a ^= low
        return res

    def mulmod(a: int, b: int) -> int:
        # Reduce modulo z^n - 1: z^(n+k) == z^k, so one fold is enough.
        p = clmul(a, b)
        return (p & mask) ^ (p >> n)

    x = 0
    for i, c in enumerate(state):
        if c == '1':
            x |= 1 << i

    # Exponentiation by squaring: x <- x * Q^t.
    base = q
    e = t
    while e:
        if e & 1:
            x = mulmod(x, base)
        e >>= 1
        if e:
            base = mulmod(base, base)

    return ''.join('1' if (x >> i) & 1 else '0' for i in range(n))
